(() => {
  const g = __rhf.game;
  g.state.settings.autoQuality = false;
  g.setQuality('low');
  g.bears.directorT = 1e9;
  g.env.timeScale = 0;
  g.env.setTime(14);
  const w = g.env.weather;
  w.rain = w.rainTarget = 0;
  w.cloud = w.cloudTarget = 0.2;
  w.timer = 1e9;
  g.hud.firstShown = -1000;
  g.hud.hint('', 0);
  __rhf.god(true);
  // the slow test renderer never finishes a style transition before a
  // picture: show the messages where they end up
  const st = document.createElement('style');
  st.textContent = '#toasts { transition: none !important; }';
  document.head.appendChild(st);
  window.__until = async (fn, ms = 240000) => {
    const t0 = performance.now();
    while (performance.now() - t0 < ms) {
      const r = fn();
      if (r) return r;
      await new Promise((q) => setTimeout(q, 200));
    }
    return null;
  };
  // stand somewhere and face something, with the ground detail finished
  window.__stand = (x, z, lookX, lookZ, pitch = 0) => {
    const P = g.player;
    P.place(x, z, Math.atan2(-(lookX - x), -(lookZ - z)));
    P.pitch = pitch;
    __rhf.settle();
  };
  window.__ia = () => (g.interaction ? g.interaction.label : '-') + ' / ' + (g.interaction2 ? g.interaction2.label : '-');
  return 'set up; secret parts: ' + Object.keys(g.props.secret).join(', ') + '; flags ' + JSON.stringify(g.state.flags);
})()

(() => {
    const g = __rhf.game;
    const ch = g.props.secret.chest;
    const f = g.world.place('falls');
    __stand(f.x, f.z, ch.x, ch.z, -0.05);
    return 'at Bear Falls, ' + Math.hypot(ch.x - f.x, ch.z - f.z).toFixed(0) + ' m from the hidden chest';
  })()

(() => {
    const g = __rhf.game;
    const ch = g.props.secret.chest;
    // on the shelf, a metre and a half west of the chest, facing it
    const F = g.props.secret;
    const dx = ch.x - g.world.place('falls').x;
    const W = g.world;
    let best = null;
    for (let a = 0; a < 64; a++) {
      const x = ch.x + Math.cos(a / 64 * Math.PI * 2) * 1.5;
      const z = ch.z + Math.sin(a / 64 * Math.PI * 2) * 1.5;
      const d = g.colliders.deckAt(x, z, 1e9, 1e9);
      if (d !== null && Math.abs(d - ch.y) < 0.05) { best = { x, z }; break; }
    }
    if (!best) return 'no shelf spot found';
    __stand(best.x, best.z, ch.x, ch.z, -0.35);
    return 'on the shelf: y ' + g.player.pos.y.toFixed(2) + ' (shelf ' + ch.y.toFixed(2) + '), actions ' + __ia();
  })()

